-- Canonical Fleet service hierarchy and ServiceWriter-style account policy model.
UPDATE public.vehicles v SET customer_id = src.customer_id, updated_at = now() FROM (SELECT DISTINCT ON (vehicle_id) vehicle_id, customer_id FROM public.appointments WHERE vehicle_id IS NOT NULL AND customer_id IS NOT NULL ORDER BY vehicle_id, updated_at DESC) src WHERE v.id = src.vehicle_id AND v.customer_id IS NULL;
UPDATE public.vehicles v SET customer_id = src.customer_id, updated_at = now() FROM (SELECT DISTINCT ON (vehicle_id) vehicle_id, customer_id FROM public.work_orders WHERE vehicle_id IS NOT NULL AND customer_id IS NOT NULL ORDER BY vehicle_id, updated_at DESC) src WHERE v.id = src.vehicle_id AND v.customer_id IS NULL;
UPDATE public.work_orders w SET customer_id = v.customer_id, updated_at = now() FROM public.vehicles v WHERE w.vehicle_id = v.id AND w.organization_id = v.organization_id AND w.customer_id IS NULL;
UPDATE public.appointments a SET customer_id = w.customer_id, vehicle_id = w.vehicle_id, updated_at = now() FROM public.work_orders w WHERE a.work_order_id = w.id AND a.organization_id = w.organization_id AND (a.customer_id IS DISTINCT FROM w.customer_id OR a.vehicle_id IS DISTINCT FROM w.vehicle_id);
UPDATE public.work_orders w SET technician_id = src.technician_id, updated_at = now() FROM (SELECT DISTINCT ON (work_order_id) work_order_id, technician_id FROM public.dispatch_assignments WHERE technician_id IS NOT NULL AND status <> 'cancelled' ORDER BY work_order_id, created_at DESC) src WHERE w.id = src.work_order_id AND w.technician_id IS DISTINCT FROM src.technician_id;
ALTER TABLE public.vehicles ALTER COLUMN customer_id SET NOT NULL;
ALTER TABLE public.work_orders ALTER COLUMN customer_id SET NOT NULL;
ALTER TABLE public.work_orders ALTER COLUMN vehicle_id SET NOT NULL;
ALTER TABLE public.appointments ALTER COLUMN work_order_id SET NOT NULL;
ALTER TABLE public.appointments ALTER COLUMN customer_id SET NOT NULL;
ALTER TABLE public.appointments ALTER COLUMN vehicle_id SET NOT NULL;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicles_org_id_customer_unique UNIQUE (organization_id,id,customer_id);
ALTER TABLE public.work_orders ADD CONSTRAINT work_orders_org_id_customer_vehicle_unique UNIQUE (organization_id,id,customer_id,vehicle_id);
ALTER TABLE public.work_orders ADD CONSTRAINT work_orders_vehicle_customer_chain_fk FOREIGN KEY (organization_id,vehicle_id,customer_id) REFERENCES public.vehicles(organization_id,id,customer_id);
ALTER TABLE public.appointments ADD CONSTRAINT appointments_work_order_chain_fk FOREIGN KEY (organization_id,work_order_id,customer_id,vehicle_id) REFERENCES public.work_orders(organization_id,id,customer_id,vehicle_id);
CREATE TABLE public.service_catalog (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES public.organizations(id), code text NOT NULL, name text NOT NULL, category text NOT NULL DEFAULT 'general', description text, default_price numeric(12,2) NOT NULL DEFAULT 0, default_labor_minutes integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, code));
CREATE TABLE public.fleet_service_agreements (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES public.organizations(id), customer_id text NOT NULL REFERENCES public.customers(id), name text NOT NULL, start_date date, end_date date, status text NOT NULL DEFAULT 'active', sla_hours integer NOT NULL DEFAULT 24, approval_mode text NOT NULL DEFAULT 'hybrid', approval_threshold numeric(12,2) NOT NULL DEFAULT 500, approver_role text NOT NULL DEFAULT 'fleet_manager', require_photo_evidence boolean NOT NULL DEFAULT false, billing_model text NOT NULL DEFAULT 'flat_rate', invoice_frequency text NOT NULL DEFAULT 'monthly', payment_terms text NOT NULL DEFAULT 'net_30', invoice_group text, po_required boolean NOT NULL DEFAULT false, po_validate_remaining boolean NOT NULL DEFAULT true, enforce_location_windows boolean NOT NULL DEFAULT true, enforce_sla_window boolean NOT NULL DEFAULT true, min_dispatch_buffer_minutes integer NOT NULL DEFAULT 15, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX fleet_service_agreements_customer_idx ON public.fleet_service_agreements(organization_id, customer_id, status);
CREATE TABLE public.fleet_agreement_services (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES public.organizations(id), agreement_id text NOT NULL REFERENCES public.fleet_service_agreements(id) ON DELETE CASCADE, service_id text NOT NULL REFERENCES public.service_catalog(id), unit_price numeric(12,2) NOT NULL, labor_minutes integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, custom_label text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (agreement_id, service_id));
CREATE TABLE public.vehicle_service_profiles (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES public.organizations(id), vehicle_id text NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, service_id text NOT NULL REFERENCES public.service_catalog(id), preferred_part_id text REFERENCES public.parts(id), interval_miles integer, interval_engine_hours integer, interval_days integer, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vehicle_id, service_id));
CREATE TABLE public.vehicle_parts (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES public.organizations(id), vehicle_id text NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE, part_id text NOT NULL REFERENCES public.parts(id), quantity numeric(12,3) NOT NULL DEFAULT 1, purpose text NOT NULL DEFAULT 'service', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vehicle_id, part_id, purpose));
ALTER TABLE public.work_orders ADD COLUMN service_agreement_id text REFERENCES public.fleet_service_agreements(id);
ALTER TABLE public.service_lines ADD COLUMN service_id text REFERENCES public.service_catalog(id);
CREATE INDEX vehicle_parts_vehicle_idx ON public.vehicle_parts(organization_id, vehicle_id);
CREATE INDEX vehicle_service_profiles_vehicle_idx ON public.vehicle_service_profiles(organization_id, vehicle_id);
CREATE INDEX fleet_agreement_services_agreement_idx ON public.fleet_agreement_services(organization_id, agreement_id);
REVOKE ALL PRIVILEGES ON TABLE public.service_catalog FROM PUBLIC, authenticated, anonymous;
REVOKE ALL PRIVILEGES ON TABLE public.fleet_service_agreements FROM PUBLIC, authenticated, anonymous;
REVOKE ALL PRIVILEGES ON TABLE public.fleet_agreement_services FROM PUBLIC, authenticated, anonymous;
REVOKE ALL PRIVILEGES ON TABLE public.vehicle_service_profiles FROM PUBLIC, authenticated, anonymous;
REVOKE ALL PRIVILEGES ON TABLE public.vehicle_parts FROM PUBLIC, authenticated, anonymous;
